// Generated from the actual GLBs in assets/obstacles with Three.js r187.
// Native model bounds are sliced at 24 × 24 column centres, sampled from both sides
// with winding-normal events, then merged over identical spans and rounded to 128 Y steps.
// Coincident opposite-winding faces keep a thin surface, including cart lattice and rock tops.
const grid = 24;
const heightSteps = 128;

function colliderModel(nativeWidth, nativeDepth, boxes) {
  return {
    nativeWidth,
    nativeDepth,
    primitives: boxes.map(([x, z, width, depth, bottom, top]) => ({
      x: x / grid,
      z: z / grid,
      w: width / grid,
      d: depth / grid,
      bottom: bottom / heightSteps,
      top: top / heightSteps,
    })),
  };
}

